// Helper function to get the icon for an activity
export function getActivityIcon(activityId: string, gender?: "boy" | "girl"): string | undefined {
  // First check for gender-specific variant
  if (gender === "girl" && GIRL_ICON_VARIANTS[activityId]) {
    return GIRL_ICON_VARIANTS[activityId];
  }
  if (gender === "boy" && BOY_ICON_VARIANTS[activityId]) {
    return BOY_ICON_VARIANTS[activityId];
  }
  
  // Fall back to default icon
  return ACTIVITY_PNG_ICONS[activityId];
}
